<script setup>
import PublicLayout from '../../Layouts/PublicLayout.vue';
import { Head, useForm } from '@inertiajs/vue3';
const props=defineProps({campaign:Object,recentDonations:Array,bankTransferDetails:Object,memberDetails:{type:Object,default:null}});
const donation=useForm({donor_name:props.memberDetails?.name ?? '',donor_email:props.memberDetails?.email ?? '',donor_phone:props.memberDetails?.phone ?? '',amount:'',is_anonymous:false,method:'paystack',transfer_reference:''});
const pledge=useForm({name:props.memberDetails?.name ?? '',email:props.memberDetails?.email ?? '',phone:props.memberDetails?.phone ?? '',amount:'',note:''});
const money=v=>'₦'+Number(v||0).toLocaleString('en-NG',{maximumFractionDigits:0});
function donate(){donation.post(`/fundraising/${props.campaign.slug}/donate`);}
function makePledge(){pledge.post(`/fundraising/${props.campaign.slug}/pledge`);}
</script>
<template><PublicLayout><Head :title="campaign.title"/><section class="bg-[#00351F] text-white"><div class="mx-auto max-w-7xl px-5 py-10"><a href="/fundraising" class="text-sm text-[#D4A72C]">← All campaigns</a><h1 class="mt-3 max-w-4xl text-3xl font-extrabold md:text-4xl">{{campaign.title}}</h1><p class="mt-3 max-w-3xl text-sm leading-7 text-white/75">{{campaign.excerpt}}</p></div></section>
<div class="mx-auto grid max-w-7xl gap-8 px-5 py-10 lg:grid-cols-[1.3fr_.9fr]"><div><img :src="campaign.image" :alt="campaign.title" class="max-h-[420px] w-full rounded-2xl object-cover"/><div class="mt-6 whitespace-pre-line text-sm leading-8 text-gray-700">{{campaign.description}}</div><div class="mt-7 rounded-2xl border bg-white p-5"><h2 class="text-lg font-extrabold text-[#00351F]">Campaign progress</h2><div class="mt-4 flex items-end justify-between gap-3"><div><p class="text-2xl font-extrabold text-[#006B3C]">{{money(campaign.raised_amount)}}</p><p class="text-xs text-gray-500">raised so far</p></div><div class="text-right"><p class="font-bold">{{money(campaign.target_amount)}}</p><p class="text-xs text-gray-500">target</p></div></div><div class="mt-3 h-3 overflow-hidden rounded-full bg-gray-100"><div class="h-full bg-[#087A3A]" :style="{width:campaign.progress+'%'}"></div></div><p class="mt-2 text-xs text-gray-500">{{campaign.progress}}% achieved · {{campaign.donor_count}} verified donations</p></div><div v-if="recentDonations.length" class="mt-6 rounded-2xl border bg-white p-5"><h2 class="font-extrabold text-[#00351F]">Recent supporters</h2><div v-for="d in recentDonations" :key="d.date+d.name" class="flex justify-between border-b py-3 text-sm last:border-0"><span>{{d.name}} <small class="block text-gray-400">{{d.date}}</small></span><b>{{money(d.amount)}}</b></div></div></div>
<aside class="space-y-6"><div class="rounded-2xl border bg-white p-6 shadow-sm"><h2 class="text-xl font-extrabold text-[#00351F]">Make a donation</h2><p class="mt-2 text-sm text-gray-600">Every contribution helps move this initiative forward.</p><form class="mt-5 space-y-4" @submit.prevent="donate"><div><label class="text-sm font-semibold">Your name</label><input v-model="donation.donor_name" :readonly="!!memberDetails" class="mt-1 w-full rounded-lg border-gray-300" placeholder="Name"/></div><div><label class="text-sm font-semibold">Email address</label><input v-model="donation.donor_email" type="email" required :readonly="!!memberDetails" class="mt-1 w-full rounded-lg border-gray-300"/></div><div><label class="text-sm font-semibold">Phone number</label><input v-model="donation.donor_phone" class="mt-1 w-full rounded-lg border-gray-300" placeholder="Phone number"/></div><div><label class="text-sm font-semibold">Donation amount (₦)</label><input v-model="donation.amount" type="number" min="100" step="1" required class="mt-1 w-full rounded-lg border-gray-300" placeholder="e.g. 5000"/></div><label class="flex items-center gap-2 text-sm"><input v-model="donation.is_anonymous" type="checkbox"/> Display my donation as Anonymous</label><div><label class="text-sm font-semibold">Payment method</label><select v-model="donation.method" class="mt-1 w-full rounded-lg border-gray-300"><option value="paystack">Pay online with Paystack</option><option value="bank_transfer">Bank transfer (pending verification)</option></select></div><div v-if="donation.method==='bank_transfer'" class="rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><b>Bank transfer details</b><p class="mt-1">{{bankTransferDetails?.bank_name || 'Bank details to be confirmed by BBHS'}}</p><p>{{bankTransferDetails?.account_name}}</p><p class="font-bold">{{bankTransferDetails?.account_number}}</p><label class="mt-3 block text-sm font-semibold">Transfer reference (if available)</label><input v-model="donation.transfer_reference" class="mt-1 w-full rounded-lg border-gray-300"/></div><p v-if="Object.keys(donation.errors).length" class="text-sm text-red-600">{{Object.values(donation.errors).join(' ')}}</p><button :disabled="donation.processing" class="w-full rounded-lg bg-[#006B3C] px-5 py-3 font-bold text-white disabled:opacity-50">{{donation.method==='paystack'?'Continue to secure payment':'Submit transfer for verification'}}</button><p class="text-xs leading-5 text-gray-500">Only verified payments are included in the campaign total. Your email is used for payment confirmation and is not displayed publicly.</p></form></div>
<div class="rounded-2xl border bg-[#F7F9F7] p-6"><h2 class="text-lg font-extrabold text-[#00351F]">Make a pledge</h2><p class="mt-1 text-sm text-gray-600">Record a contribution you intend to fulfil later.</p><form class="mt-4 space-y-3" @submit.prevent="makePledge"><input v-model="pledge.name" required :readonly="!!memberDetails" placeholder="Your name" class="w-full rounded-lg border-gray-300"/><input v-model="pledge.email" required type="email" :readonly="!!memberDetails" placeholder="Email address" class="w-full rounded-lg border-gray-300"/><input v-model="pledge.phone" placeholder="Phone number" class="w-full rounded-lg border-gray-300"/><input v-model="pledge.amount" required type="number" min="100" placeholder="Pledge amount (₦)" class="w-full rounded-lg border-gray-300"/><textarea v-model="pledge.note" placeholder="Optional note" class="w-full rounded-lg border-gray-300"></textarea><button :disabled="pledge.processing" class="w-full rounded-lg border border-[#006B3C] px-4 py-3 font-bold text-[#006B3C]">Submit pledge</button></form></div></aside></div></PublicLayout></template>
